import React from 'react';

interface SoundToggleProps {
  soundMode: 'off' | 'default' | 'alt';
  onSoundModeChange: (mode: 'off' | 'default' | 'alt') => void;
}

const SoundToggle: React.FC<SoundToggleProps> = ({ soundMode, onSoundModeChange }) => {
  const modes = [
    { key: 'off', label: 'OFF', icon: '🔇' },
    { key: 'default', label: 'DEFAULT', icon: '🎵' },
    { key: 'alt', label: 'ALT', icon: '🎶' }
  ] as const;

  const currentIndex = modes.findIndex(mode => mode.key === soundMode);

  const nextMode = () => {
    const nextIndex = (currentIndex + 1) % modes.length;
    onSoundModeChange(modes[nextIndex].key);
  };

  const prevMode = () => {
    const prevIndex = (currentIndex - 1 + modes.length) % modes.length;
    onSoundModeChange(modes[prevIndex].key);
  };

  return (
    <div className="bg-black/5 rounded-2xl p-3 border border-black/10 shadow-inner">
      <div className="flex items-center gap-2">
        {/* Label */}
        <div className="flex flex-col">
          <span className="text-black/70 text-[8px] font-black uppercase tracking-tighter">Peg Sounds</span>
          <span className="text-black font-mono font-bold text-xs">
            {modes[currentIndex].label}
          </span>
        </div>

        {/* Toggle Buttons */}
        <div className="flex items-center gap-1 ml-auto">
          <button
            onClick={prevMode}
            className="w-6 h-6 rounded-full bg-black/10 hover:bg-black/20 flex items-center justify-center text-black border border-black/20 hover:border-black/30 transition-all duration-200 text-xs"
          >
            ‹
          </button>

          {/* Current Mode Indicator */}
          <div className="flex items-center gap-1 px-2 py-1 bg-black/10 rounded-lg border border-black/20">
            <span className="text-sm">{modes[currentIndex].icon}</span>
            <span className="text-black font-bold text-[10px] uppercase tracking-wider">
              {modes[currentIndex].label}
            </span>
          </div>

          <button
            onClick={nextMode}
            className="w-6 h-6 rounded-full bg-black/10 hover:bg-black/20 flex items-center justify-center text-black border border-black/20 hover:border-black/30 transition-all duration-200 text-xs"
          >
            ›
          </button>
        </div>
      </div>
    </div>
  );
};

export default SoundToggle;
