'use client'

import React, { useState, useCallback, useRef, useEffect } from 'react';
import PlinkoGame from '../components/PlinkoGame';
import SoundToggle from '../components/SoundToggle';
import { GameState, RiskLevel } from '../types';
import { COLORS } from '../constants';

interface HistoryItem {
  id: number;
  multiplier: number;
  risk: RiskLevel;
}

const Home: React.FC = () => {
  const [gameState, setGameState] = useState<GameState>({
    balance: 755.37,
    ballCount: 0
  });

  const [wager, setWager] = useState(0.30);
  const [lastDrop, setLastDrop] = useState<{ id: number; risk: RiskLevel } | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isAutoDrop, setIsAutoDrop] = useState(false);
  const [showAutoDropModal, setShowAutoDropModal] = useState(false);
  const [autoDropSettings, setAutoDropSettings] = useState({
    ballCount: 10,
    riskLevel: 'GREEN' as RiskLevel,
    customBallCount: '',
  });
  const [remainingBalls, setRemainingBalls] = useState(0);
  const [backgroundIndex, setBackgroundIndex] = useState(0);
  const [pegSoundMode, setPegSoundMode] = useState<'off' | 'default' | 'alt'>('default');
  const lastRiskRef = useRef<RiskLevel>('GREEN');

  // Background images array
  const backgrounds = [
    '/ui/bg1.jpg',
    '/ui/bg2.jpg',
    '/ui/bg3.jpg',
    '/ui/bg4.jpg'
  ];

  // Cycle through backgrounds every 8 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setBackgroundIndex((prev) => (prev + 1) % backgrounds.length);
    }, 8000);

    return () => clearInterval(interval);
  }, [backgrounds.length]);

  const handleScore = useCallback((multiplier: number) => {
    setGameState(prev => ({
      ...prev,
      balance: prev.balance + (wager * multiplier)
    }));

    setHistory(prev => [
      { id: Date.now(), multiplier, risk: lastRiskRef.current },
      ...prev
    ].slice(0, 15));
  }, [wager]);

  const dropBall = useCallback((risk: RiskLevel) => {
    setGameState(prev => {
      if (prev.balance < wager) {
        setIsAutoDrop(false);
        return prev;
      }
      lastRiskRef.current = risk;
      setLastDrop({ id: Date.now(), risk });
      return {
        ...prev,
        balance: prev.balance - wager,
        ballCount: prev.ballCount + 1
      };
    });
  }, [wager]);

  // Auto Drop Logic
  useEffect(() => {
    let interval: number | null = null;
    if (isAutoDrop && remainingBalls > 0) {
      interval = window.setInterval(() => {
        dropBall(autoDropSettings.riskLevel);
        setRemainingBalls(prev => {
          const newCount = prev - 1;
          if (newCount <= 0) {
            setIsAutoDrop(false);
            setRemainingBalls(0);
          }
          return newCount;
        });
      }, 1000); // Fixed 1 second interval
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isAutoDrop, dropBall, remainingBalls, autoDropSettings.riskLevel]);

  const adjustWager = (amount: number) => {
    setWager(prev => Math.max(0.1, +(prev + amount).toFixed(2)));
  };


  return (
    <div
      className="flex flex-col h-screen w-full overflow-hidden bg-white transition-all duration-1000"
    >
      {/* HEADER SECTION */}
      <header className="flex justify-between items-center px-4 py-3 z-30 bg-black/5 backdrop-blur-sm border-b border-black/20">
        {/* History (Left) */}
        <div className="flex items-center gap-2 max-w-[60%] overflow-hidden">
          <div className="flex gap-1 overflow-x-auto no-scrollbar scroll-smooth">
            {history.length > 0 ? history.map((item, index) => (
              <div
                key={item.id}
                className={`bg-black/10 hover:bg-black/20 px-2.5 py-0.5 rounded text-[10px] font-black min-w-fit border border-black/20 text-black shadow-sm transition-all duration-300 hover:scale-105 animate-in fade-in slide-in-from-right-2`}
                style={{
                  animationDelay: `${index * 100}ms`,
                  animationFillMode: 'both'
                }}
              >
                {item.multiplier}x
              </div>
            )) : (
              <div className="text-[10px] text-black/50 font-bold uppercase tracking-widest px-1 italic">Waiting for results...</div>
            )}
          </div>
        </div>

        {/* Balance (Right) */}
        <div className="flex items-center gap-2 bg-black/10 px-4 py-1.5 rounded-xl border border-black/20 shadow-inner hover:bg-black/15 transition-colors duration-200">
          <span className="text-black font-black text-sm tracking-tight">
            {gameState.balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
          <span className="text-black/80 text-[8px] font-black">USD</span>
        </div>
      </header>

      {/* MAIN CONTENT - Responsive 2-column layout */}
      <main className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-0 lg:gap-6 p-4 lg:p-6 overflow-hidden">
        {/* GAME BOARD - Left side on large screens */}
        <div className="order-1 lg:order-1 w-full h-full flex justify-center items-center bg-black/5 rounded-2xl border border-black/10 shadow-inner">
          <PlinkoGame
            onScore={handleScore}
            lastDrop={lastDrop}
            pegSoundMode={pegSoundMode}
          />
        </div>

        {/* CONTROLS - Bottom on mobile, right side on large screens */}
        <div className="order-2 lg:order-2 space-y-6">
          <div className="flex flex-col gap-4">
            {/* Wager Control with Auto Drop */}
            <div className="bg-black/5 rounded-2xl p-3 border border-black/10 shadow-inner hover:bg-black/10 transition-colors duration-200">
              <div className="grid grid-cols-3 gap-3 items-center">
                {/* Wager Amount Display */}
                <div className="flex flex-col items-start">
                  <span className="text-black/70 text-[8px] font-black uppercase tracking-tighter">Wager USD</span>
                  <div className="text-black font-mono font-bold text-base">
                    {wager.toFixed(2)}
                  </div>
                </div>

                {/* Preset Buttons */}
                <div className="flex flex-col gap-1">
                  <button
                    onClick={() => setWager(Math.max(0.1, wager / 2))}
                    className="w-full h-6 rounded-lg bg-black/10 backdrop-blur-sm flex items-center justify-center text-black border border-black/20 hover:bg-black/20 hover:border-black/30 active:scale-95 transition-all duration-200 text-[9px] font-bold shadow-md"
                  >
                    ½
                  </button>
                  <button
                    onClick={() => setWager(wager * 2)}
                    className="w-full h-6 rounded-lg bg-black/10 backdrop-blur-sm flex items-center justify-center text-black border border-black/20 hover:bg-black/20 hover:border-black/30 active:scale-95 transition-all duration-200 text-[9px] font-bold shadow-md"
                  >
                    2×
                  </button>
                </div>

                {/* Controls Column */}
                <div className="flex flex-col gap-2">
                  {/* +/- Buttons */}
                  <div className="flex items-center gap-1 justify-center">
                    <button onClick={() => adjustWager(-0.1)} className="w-8 h-8 rounded-full bg-black/5 flex items-center justify-center text-black border border-black/20 hover:bg-black/10 hover:border-black/30 active:scale-90 transition-all duration-200 text-sm">-</button>
                    <button onClick={() => adjustWager(0.1)} className="w-8 h-8 rounded-full bg-black/5 flex items-center justify-center text-black border border-black/20 hover:bg-black/10 hover:border-black/30 active:scale-90 transition-all duration-200 text-sm">+</button>
                  </div>

                  {/* Auto Drop Button */}
                  <button
                    onClick={() => {
                      if (isAutoDrop) {
                        setIsAutoDrop(false);
                        setRemainingBalls(0);
                      } else {
                        setShowAutoDropModal(true);
                      }
                    }}
                    className={`w-full h-8 rounded-lg transition-all duration-200 border backdrop-blur-sm shadow-md hover:shadow-lg relative overflow-hidden text-[8px] font-bold ${
                      isAutoDrop
                        ? 'bg-black/20 border-black/40 text-black shadow-black/10 laser-border'
                        : 'bg-black/10 border-black/20 text-black/70 hover:text-black hover:bg-black/15'
                    }`}
                  >
                    <span className="uppercase tracking-widest">
                      {isAutoDrop ? `${remainingBalls}` : 'Auto'}
                    </span>
                  </button>
                </div>
              </div>
            </div>

            {/* Sound Toggle */}
            <SoundToggle
              soundMode={pegSoundMode}
              onSoundModeChange={setPegSoundMode}
            />

            {/* Risk Buttons */}
            <div className="flex gap-2 flex-1">
              <button
                onClick={() => dropBall('GREEN')}
                className="bg-black/10 hover:bg-black/20 active:scale-95 transition-all duration-200 text-black font-black py-3 rounded-xl text-[10px] tracking-widest shadow-lg hover:shadow-xl border border-black/20 uppercase flex-1"
              >
                Low
              </button>
              <button
                onClick={() => dropBall('YELLOW')}
                className="bg-black/15 hover:bg-black/25 active:scale-95 transition-all duration-200 text-black font-black py-3 rounded-xl text-[10px] tracking-widest shadow-lg hover:shadow-xl border border-black/20 uppercase flex-1"
              >
                Medium
              </button>
              <button
                onClick={() => dropBall('RED')}
                className="bg-black/20 hover:bg-black/30 active:scale-95 transition-all duration-200 text-black font-black py-3 rounded-xl text-[10px] tracking-widest shadow-lg hover:shadow-xl border border-black/20 uppercase flex-1"
              >
                High
              </button>
            </div>
          </div>
        </div>
      </main>

      {/* Auto Drop Settings Modal */}
      {showAutoDropModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl p-6 max-w-md w-full shadow-2xl">
            <h3 className="text-xl font-bold text-black mb-6 text-center">Auto Drop Settings</h3>

            {/* Ball Count Selection */}
            <div className="mb-6">
              <label className="block text-sm font-semibold text-black/80 mb-3">Number of Balls</label>
              <div className="grid grid-cols-3 gap-2 mb-3">
                {[5, 10, 20].map(count => (
                  <button
                    key={count}
                    onClick={() => setAutoDropSettings(prev => ({ ...prev, ballCount: count, customBallCount: '' }))}
                    className={`py-2 px-3 rounded-lg text-sm font-bold transition-all ${
                      autoDropSettings.ballCount === count && autoDropSettings.customBallCount === ''
                        ? 'bg-black text-white'
                        : 'bg-black/10 text-black hover:bg-black/20'
                    }`}
                  >
                    {count}
                  </button>
                ))}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {[50, 100].map(count => (
                  <button
                    key={count}
                    onClick={() => setAutoDropSettings(prev => ({ ...prev, ballCount: count, customBallCount: '' }))}
                    className={`py-2 px-3 rounded-lg text-sm font-bold transition-all ${
                      autoDropSettings.ballCount === count && autoDropSettings.customBallCount === ''
                        ? 'bg-black text-white'
                        : 'bg-black/10 text-black hover:bg-black/20'
                    }`}
                  >
                    {count}
                  </button>
                ))}
                <input
                  type="number"
                  placeholder="Custom"
                  value={autoDropSettings.customBallCount}
                  onChange={(e) => {
                    const value = e.target.value;
                    const numValue = parseInt(value) || 0;
                    setAutoDropSettings(prev => ({
                      ...prev,
                      customBallCount: value,
                      ballCount: numValue > 0 ? numValue : prev.ballCount
                    }));
                  }}
                  className="py-2 px-3 rounded-lg text-sm border border-black/20 bg-white text-black placeholder-black/50 focus:border-black focus:outline-none"
                  min="1"
                  max="1000"
                />
              </div>
            </div>

            {/* Risk Level Selection */}
            <div className="mb-8">
              <label className="block text-sm font-semibold text-black/80 mb-3">Risk Level</label>
              <div className="space-y-2">
                {[
                  { key: 'GREEN', label: 'Low Risk', desc: 'Safer, lower rewards' },
                  { key: 'YELLOW', label: 'Medium Risk', desc: 'Balanced risk/reward' },
                  { key: 'RED', label: 'High Risk', desc: 'Higher risk, higher rewards' }
                ].map(({ key, label, desc }) => (
                  <button
                    key={key}
                    onClick={() => setAutoDropSettings(prev => ({ ...prev, riskLevel: key as RiskLevel }))}
                    className={`w-full p-3 rounded-lg text-left transition-all ${
                      autoDropSettings.riskLevel === key
                        ? 'bg-black text-white'
                        : 'bg-black/10 text-black hover:bg-black/20'
                    }`}
                  >
                    <div className="font-bold text-sm">{label}</div>
                    <div className={`text-xs ${autoDropSettings.riskLevel === key ? 'text-white/80' : 'text-black/60'}`}>
                      {desc}
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-3">
              <button
                onClick={() => setShowAutoDropModal(false)}
                className="flex-1 py-3 px-4 bg-black/10 text-black font-bold rounded-lg hover:bg-black/20 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  const ballCount = autoDropSettings.customBallCount
                    ? parseInt(autoDropSettings.customBallCount) || autoDropSettings.ballCount
                    : autoDropSettings.ballCount;
                  setRemainingBalls(ballCount);
                  setIsAutoDrop(true);
                  setShowAutoDropModal(false);
                }}
                className="flex-1 py-3 px-4 bg-black text-white font-bold rounded-lg hover:bg-black/80 transition-all"
              >
                Start Auto Drop
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Home;
